      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and tests of fundamental physics by combining narrow optical transitions with confinement that suppresses motion-related shifts.",
        "attribution": "Katori proposed and demonstrated the lattice-clock concept; Ye made major independent contributions to its experimental realization and precision.",
        "maturity": "The approach is experimentally established, independently reproduced, and continues to improve precision and applications.",
        "uncertainties": [
          "The boundary between the original clock invention and subsequent precision advances merits careful historical attribution."
        ]
      }
    },
