      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page Jr.",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "Precision maps of cosmic microwave background anisotropies made the early universe a quantitative field of experimental cosmology and constrained its fundamental parameters.",
        "attribution": "Bennett and Page represent major experimental leadership in space-based mapping; Spergel made influential contributions to extracting cosmological meaning from the measurements.",
        "maturity": "The results have been confirmed and sharpened by successive experiments and underpin a durable standard cosmological framework.",
        "uncertainties": [
          "The long, international instrument and analysis contributions are difficult to represent with three individual laureates.",
          "The credited names span distinct missions and contributions, so the specific discovery scope needs precise definition."
        ]
      }
    },
