      "rank": 4,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman",
        "James M. Moran"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale imaging of black holes was a striking experimental achievement that tested strong-gravity predictions and made otherwise inaccessible compact objects observable.",
        "attribution": "Falcke developed the early imaging proposal, Doeleman led key experimental efforts, and Moran contributed to the foundational very-long-baseline interferometry work and its application.",
        "maturity": "The images have been published, scrutinized, and complemented by a second black-hole target, though the technique and interpretation continue to develop.",
        "uncertainties": [
          "The result depended on a large collaboration; individual credit for the original idea, instrument development, and final imaging requires scrutiny."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Duncan Lorimer",
        "Maura McLaughlin",
        "Matthew Bailes"
      ],
      "assessment": {
        "nobel_worthiness": "Fast radio bursts revealed a new class of energetic, brief cosmic transients and have become valuable probes of matter and magnetized environments between galaxies.",
        "attribution": "Lorimer and McLaughlin were central to identifying and interpreting the first burst in archival data; Bailes contributed to the observing program and its scientific context.",
        "maturity": "The phenomenon is now established through many detections, with repeaters and localized sources confirming its astrophysical reality.",
        "uncertainties": [
          "The discovery trail runs from the original observation through later identification and follow-up, so priority and each person's role need careful verification."
        ]
      }
    },
    {
      "rank": 6,
