      "proposed_laureates": [
        "Hideo Hosono",
        "Xianhui Chen",
        "Zhongxian Zhao"
      ],
      "assessment": {
        "nobel_worthiness": "Iron-based high-temperature superconductors expanded the known families of superconductors and reopened fundamental questions about unconventional pairing.",
        "attribution": "Hosono's discovery of superconductivity in iron pnictides was followed by independent, rapid discoveries by Chen and Zhao that established the broader family.",
        "maturity": "The materials and superconducting phases are well established, although a complete microscopic account of pairing remains unsettled.",
        "uncertainties": [
          "The relative distinction between the first discovery and independent confirmation or extension should determine the final attribution."
        ]
      }
    },
